<?php

declare(strict_types=1);

namespace App\Filament\Customer\Concerns;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;

/**
 * Scopes a customer-panel resource to the signed-in customer.
 *
 * Two things happen here, and both matter.
 *
 * The query is scoped, so there is no URL that can return somebody else's row even before
 * authorisation runs — a record that is not in the query is a 404, not a 403.
 *
 * Authorisation is answered by ownership rather than by deferring to the model's policy.
 * Those policies are generated by Shield for the staff panel and ask whether the actor
 * holds a permission like "ViewAny:Order"; a customer holds none, so inheriting them would
 * lock every customer out of their own account. Ownership is the right question on this
 * panel, and asking it explicitly is clearer than granting customers staff permissions.
 */
trait BelongsToCustomer
{
    public static function getEloquentQuery(): Builder
    {
        return parent::getEloquentQuery()->where('user_id', auth()->id());
    }

    public static function canViewAny(): bool
    {
        return auth()->check();
    }

    public static function canView(Model $record): bool
    {
        return $record->getAttribute('user_id') === auth()->id();
    }

    public static function canCreate(): bool
    {
        return false;
    }

    public static function canEdit(Model $record): bool
    {
        return false;
    }

    public static function canDelete(Model $record): bool
    {
        return false;
    }

    public static function canDeleteAny(): bool
    {
        return false;
    }
}
